119	  const [isNavOpen, setIsNavOpen] = useState(false);
120	  const sidecarConfig = useObservable(observables.sidecarConfig$, undefined);
121	
122	  const sidecarPaddingStyle = useMemo(() => {
123	    return getOsdSidecarPaddingStyle(sidecarConfig);
124	  }, [sidecarConfig]);
