134	
135	  const expandedHeaderColorScheme: EuiHeaderProps['theme'] = 'dark';
136	
137	  return (
138	    <>
139	      <header className={className} data-test-subj="headerGlobalNav">
140	        <div id="globalHeaderBars">
141	          {useExpandedHeader && (
142	            <EuiHeader
143	              className="expandedHeader"
144	              theme={expandedHeaderColorScheme}
145	              style={sidecarPaddingStyle}
146	              position="fixed"
147	              sections={[
148	                {
149	                  items: [
150	                    <HeaderLogo
151	                      href={homeHref}
152	                      forceNavigation$={observables.forceAppSwitcherNavigation$}
153	                      navLinks$={observables.navLinks$}
154	                      navigateToApp={application.navigateToApp}
155	                      branding={branding}
156	                      logos={logos}
157	                      /* This color-scheme should match the `theme` of the parent EuiHeader */
158	                      backgroundColorScheme={expandedHeaderColorScheme}
159	                    />,
160	                  ],
161	                  borders: 'none',
162	                },
163	                {
164	                  items: [
165	                    <EuiShowFor sizes={['m', 'l', 'xl']}>
166	                      <HeaderNavControls navControls$={observables.navControlsExpandedCenter$} />
167	                    </EuiShowFor>,
168	                  ],
169	                  borders: 'none',
170	                },
171	                {
172	                  items: [
173	                    <EuiHideFor sizes={['m', 'l', 'xl']}>
174	                      <HeaderNavControls navControls$={observables.navControlsExpandedCenter$} />
175	                    </EuiHideFor>,
176	                    <HeaderNavControls navControls$={observables.navControlsExpandedRight$} />,
177	                  ],
178	                  borders: 'none',
179	                },
180	              ]}
181	            />
182	          )}
183	
184	          <EuiHeader position="fixed" className="primaryHeader" style={sidecarPaddingStyle}>
185	            <EuiHeaderSection grow={false}>
186	              <EuiHeaderSectionItem border="right" className="header__toggleNavButtonSection">
187	                <EuiHeaderSectionItemButton
188	                  data-test-subj="toggleNavButton"
189	                  aria-label={i18n.translate('core.ui.primaryNav.toggleNavAriaLabel', {
190	                    defaultMessage: 'Toggle primary navigation',
191	                  })}
