69	/** @internal */
70	export class ChromeNavGroupService {
71	  private readonly navGroupsMap$ = new BehaviorSubject<Record<string, NavGroupItemInMap>>({});
72	  private readonly stop$ = new ReplaySubject(1);
73	  private navLinks$: Observable<Array<Readonly<ChromeNavLink>>> = new BehaviorSubject([]);
74	  private navGroupEnabled: boolean = false;
75	  private navGroupEnabledUiSettingsSubscription: Subscription | undefined;
76	  private navGroupUpdaters$$ = new BehaviorSubject<Array<Observable<ChromeNavGroupUpdater>>>([]);
77	  private currentNavGroup$ = new BehaviorSubject<ChromeNavGroup | undefined>(undefined);
78	
79	  private addNavLinkToGroup(
80	    currentGroupsMap: Record<string, NavGroupItemInMap>,
81	    navGroup: ChromeNavGroup,
82	    navLink: ChromeRegistrationNavLink
83	  ) {
84	    const matchedGroup = currentGroupsMap[navGroup.id];
85	    if (matchedGroup) {
86	      const links = matchedGroup.navLinks;
87	      const isLinkExistInGroup = links.some((link) => link.id === navLink.id);
88	      if (isLinkExistInGroup) {
89	        // eslint-disable-next-line no-console
90	        console.warn(
91	          `[ChromeService] Navlink of ${navLink.id} has already been registered in group ${navGroup.id}`
92	        );
93	        return currentGroupsMap;
94	      }
95	      matchedGroup.navLinks.push(navLink);
96	    } else {
97	      currentGroupsMap[navGroup.id] = {
98	        ...navGroup,
99	        navLinks: [navLink],
100	      };
101	    }
102	
103	    return currentGroupsMap;
104	  }
105	
106	  private sortNavGroupNavLinks(
107	    navGroup: NavGroupItemInMap,
108	    allVaildNavLinks: Array<Readonly<ChromeNavLink>>
109	  ) {
110	    return flattenLinksOrCategories(
111	      getOrderedLinksOrCategories(
112	        fulfillRegistrationLinksToChromeNavLinks(navGroup.navLinks, allVaildNavLinks)
113	      )
114	    );
115	  }
116	
117	  private getSortedNavGroupsMap$() {
118	    return combineLatest([this.getUpdatedNavGroupsMap$(), this.navLinks$])
119	      .pipe(takeUntil(this.stop$))
120	      .pipe(
121	        map(([navGroupsMap, navLinks]) => {
122	          return Object.keys(navGroupsMap).reduce((sortedNavGroupsMap, navGroupId) => {
123	            const navGroup = navGroupsMap[navGroupId];
124	            sortedNavGroupsMap[navGroupId] = {
125	              ...navGroup,
126	              navLinks: this.sortNavGroupNavLinks(navGroup, navLinks),
127	            };
128	            return sortedNavGroupsMap;
129	          }, {} as Record<string, NavGroupItemInMap>);
130	        })
131	      );
132	  }
133	
134	  private getUpdatedNavGroupsMap$() {
135	    return combineLatest([this.navGroupsMap$, this.navGroupUpdaters$$]).pipe(
136	      switchMap(([navGroupsMap, updaters$]) => {
137	        if (updaters$.length === 0) {
138	          return of(navGroupsMap);
139	        }
140	        return combineLatest(updaters$).pipe(
141	          map((updaters) => {
142	            return Object.keys(navGroupsMap).reduce<Record<string, NavGroupItemInMap>>(
143	              (previousValue, currentKey) => ({
144	                ...previousValue,
145	                [currentKey]: updaters.reduce(
146	                  (prevNavGroup, currentUpdater) => ({
147	                    ...prevNavGroup,
148	                    ...currentUpdater(prevNavGroup),
149	                  }),
150	                  navGroupsMap[currentKey]
151	                ),
152	              }),
153	              {}
154	            );
155	          })
156	        );
157	      })
158	    );
159	  }
160	  setup({ uiSettings }: { uiSettings: IUiSettingsClient }): ChromeNavGroupServiceSetupContract {
161	    this.navGroupEnabledUiSettingsSubscription = uiSettings
162	      .get$('home:useNewHomePage', false)
163	      .subscribe((value) => {
164	        this.navGroupEnabled = value;
165	      });
166	
167	    return {
168	      addNavLinksToGroup: (navGroup: ChromeNavGroup, navLinks: ChromeRegistrationNavLink[]) => {
169	        // Construct a new groups map pointer.
170	        const currentGroupsMap = { ...this.navGroupsMap$.getValue() };
171	
172	        const navGroupsMapAfterAdd = navLinks.reduce(
173	          (groupsMap, navLink) => this.addNavLinkToGroup(groupsMap, navGroup, navLink),
174	          currentGroupsMap
175	        );
176	
177	        this.navGroupsMap$.next(navGroupsMapAfterAdd);
178	      },
179	      getNavGroupEnabled: () => this.navGroupEnabled,
180	      registerNavGroupUpdater: (updater$) => {
181	        this.navGroupUpdaters$$.next([...this.navGroupUpdaters$$.getValue(), updater$]);
182	        return () => {
183	          this.navGroupUpdaters$$.next(
184	            this.navGroupUpdaters$$.getValue().filter((item) => item !== updater$)
185	          );
186	        };
187	      },
188	    };
189	  }
190	  async start({
191	    navLinks,
192	    application,
193	  }: {
194	    navLinks: ChromeNavLinks;
195	    application: InternalApplicationStart;
196	  }): Promise<ChromeNavGroupServiceStartContract> {
197	    this.navLinks$ = navLinks.getNavLinks$();
198	
199	    const currentNavGroupId = sessionStorage.getItem(CURRENT_NAV_GROUP_ID);
200	    this.currentNavGroup$ = new BehaviorSubject<ChromeNavGroup | undefined>(
201	      currentNavGroupId ? this.navGroupsMap$.getValue()[currentNavGroupId] : undefined
202	    );
203	
